// C program for the function called count_digits
// Contains target function implementation and dependency signatures

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Target function implementation
uint8_t count_digits(uint8_t *number, uint8_t N)
{
    if (number == NULL || N == 0)
    {
        return 0;
    }

    uint8_t start_pos = N - 1;
    while (start_pos > 0 && number[start_pos] == 0) start_pos--;

    /* Handle case of all zeros */
    if (start_pos == 0 && number[0] == 0)
    {
        return 1;  /* Zero has 1 digit */
    }

    return start_pos + 1;
}

